import numpy as np

def solve(values, k):
    values_arr = np.asanyarray(values)
    if values_arr.size == 0:
        return np.array([0], dtype=np.float64)

    result_sum = np.sum(values_arr[::k])
    return np.array([result_sum], dtype=np.float64)
