import numpy as np

def solve(labels):
    labels = np.asanyarray(labels)
    if labels.size == 0:
        return np.array([-99.], dtype=np.float64)

    unique, counts = np.unique(labels, return_counts=True)
    max_count = np.max(counts)

    if np.sum(counts == max_count) > 1:
        return np.array([-99.], dtype=np.float64)

    best_label = unique[np.argmax(counts)]
    return np.array([best_label], dtype=np.float64)
