import numpy as np

def solve(labels):
    if len(labels) == 0:
        return np.array([-88.0], dtype=np.float64)

    # Get unique labels and their corresponding frequencies
    u, counts = np.unique(labels, return_counts=True)

    # Find distinct frequency values (np.unique returns them sorted ascending)
    distinct_counts = np.unique(counts)

    # Check if there are at least two distinct frequencies
    if len(distinct_counts) < 2:
        return np.array([-88.0], dtype=np.float64)

    # The second largest distinct frequency is the second to last element in sorted distinct_counts
    target_freq = distinct_counts[-2]

    # Identify labels that have this specific frequency
    labels_with_freq = u[counts == target_freq]

    # Return the label if exactly one exists with that frequency, otherwise return -88
    if len(labels_with_freq) != 1:
        return np.array([-88.0], dtype=np.float64)

    return np.array([labels_with_freq[0]], dtype=np.float64)
